INSERT OR REPLACE INTO confessional_documents (id, slug, title, year, tradition, format, authors, source) VALUES (100, 'thirty_nine_articles', 'The Thirty-Nine Articles of Religion', 1571, 'anglican', 'confession', NULL, 'Church of England, Articles of Religion from The Book of Common Prayer (1662). Public domain. Retrieved from churchofengland.org/prayer-and-worship/worship-texts-and-resources/book-common-prayer/articles-religion');
INSERT OR REPLACE INTO confessional_documents (id, slug, title, year, tradition, format, authors, source) VALUES (101, 'wesleys_25_articles', 'The Articles of Religion (Methodist)', 1784, 'methodist', 'confession', 'John Wesley', 'Philip Schaff, Creeds of Christendom, vol. III (1877), pp. 807-812. Public domain. Text based on Doctrines and Discipline of the Methodist Episcopal Church, ed. Bishop Harris, New York, 1872. Retrieved from CCEL, ccel.org/ccel/schaff/creeds3');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100001, 100, 1, 'Of Faith in the Holy Trinity', 1, 'There is but one living and true God, everlasting, without body, parts, or passions; of infinite power, wisdom, and goodness; the Maker, and Preserver of all things both visible and invisible. And in unity of this Godhead there be three Persons, of one substance, power, and eternity; the Father, the Son, and the Holy Ghost.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100002, 100, 2, 'Of the Word or Son of God, which was made very Man', 1, 'The Son, which is the Word of the Father, begotten from everlasting of the Father, the very and eternal God, and of one substance with the Father, took Man''s nature in the womb of the blessed Virgin, of her substance: so that two whole and perfect Natures, that is to say, the Godhead and Manhood, were joined together in one Person, never to be divided, whereof is one Christ, very God, and very Man; who truly suffered, was crucified, dead, and buried, to reconcile his Father to us, and to be a sacrifice, not only for original guilt, but also for all actual sins of men.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100003, 100, 3, 'Of the going down of Christ into Hell', 1, 'As Christ died for us, and was buried, so also is it to be believed, that he went down into Hell.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100004, 100, 4, 'Of the Resurrection of Christ', 1, 'Christ did truly rise again from death, and took again his body, with flesh, bones, and all things appertaining to the perfection of Man''s nature; wherewith he ascended into Heaven, and there sitteth, until he return to judge all Men at the last day.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100005, 100, 5, 'Of the Holy Ghost', 1, 'The Holy Ghost, proceeding from the Father and the Son, is of one substance, majesty, and glory, with the Father and the Son, very and eternal God.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100006, 100, 6, 'Of the Sufficiency of the holy Scriptures for salvation', 1, 'Holy Scripture containeth all things necessary to salvation: so that whatsoever is not read therein, nor may be proved thereby, is not to be required of any man, that it should be believed as an article of the Faith, or be thought requisite or necessary to salvation. In the name of the holy Scripture we do understand those Canonical Books of the Old and New Testament, of whose authority was never any doubt in the Church. Of the Names and Number of the Canonical Books Genesis Exodus Leviticus Numbers Deuteronomy Joshua Judges Ruth The First Book of Samuel The Second Book of Samuel The First Book of Kings The Second Book of Kings The First Book of Chronicles The Second Book of Chronicles The First Book of Esdras The Second Book of Esdras The Book of Esther The Book of Job The Psalms The Proverbs Ecclesiastes or Preacher Cantica, or Songs of Solomon Four Prophets the greater Twelve Prophets the less And the other Books (as Hierome saith) the Church doth read for example of life and instruction of manners; but yet doth it not apply them to establish any doctrine; such are these following: The Third Book of Esdras The Fourth Book of Esdras The Book of Tobias The Book of Judith The rest of the Book of Esther The Book of Wisdom Jesus the Son of Sirach Baruch the Prophet The Song of the Three Children The Story of Susanna Of Bel and the Dragon The Prayer of Manasses The First Book of Maccabees The Second Book of Maccabees All the Books of the New Testament, as they are commonly received, we do receive, and account them Canonical.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100007, 100, 7, 'Of the Old Testament', 1, 'The Old Testament is not contrary to the New: for both in the Old and New Testament everlasting life is offered to Mankind by Christ, who is the only Mediator between God and Man, being both God and Man. Wherefore they are not to be heard, which feign that the old Fathers did look only for transitory promises. Although the Law given from God by Moses, as touching Ceremonies and Rites, do not bind Christian men, nor the Civil precepts thereof ought of necessity to be received in any commonwealth; yet notwithstanding, no Christian man whatsoever is free from the obedience of the Commandments which are called Moral.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100008, 100, 8, 'Of the Three Creeds', 1, 'The Three Creeds, Nicene Creed, Athanasius''s Creed, and that which is commonly called the Apostles'' Creed, ought thoroughly to be received and believed: for they may be proved by most certain warrants of holy Scripture.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100009, 100, 9, 'Of Original or Birth-sin', 1, 'Original Sin standeth not in the following of Adam, (as the Pelagians do vainly talk;) but it is the fault and corruption of the Nature of every man, that naturally is ingendered of the offspring of Adam; whereby man is very far gone from original righteousness, and is of his own nature inclined to evil, so that the flesh lusteth always contrary to the spirit; and therefore in every person born into this world, it deserveth God''s wrath and damnation. And this infection of nature doth remain, yea in them that are regenerated; whereby the lust of the flesh, called in the Greek, "Phronema Sarkos", which some do expound the wisdom, some sensuality, some the affection, some the desire, of the flesh, is not subject to the Law of God. And although there is no condemnation for them that believe and are baptized, yet the Apostle doth confess, that concupiscence and lust hath of itself the nature of sin.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100010, 100, 10, 'Of Free-Will', 1, 'The condition of Man after the fall of Adam is such, that he cannot turn and prepare himself, by his own natural strength and good works, to faith, and calling upon God: Wherefore we have no power to do good works pleasant and acceptable to God, without the grace of God by Christ preventing us, that we may have a good will, and working with us, when we have that good will.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100011, 100, 11, 'Of the Justification of Man', 1, 'We are accounted righteous before God, only for the merit of our Lord and Saviour Jesus Christ by Faith, and not for our own works or deservings: Wherefore, that we are justified by Faith only is a most wholesome Doctrine, and very full of comfort, as more largely is expressed in the Homily of Justification.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100012, 100, 12, 'Of Good Works', 1, 'Albeit that Good Works, which are the fruits of Faith, and follow after Justification, cannot put away our sins, and endure the severity of God''s Judgement; yet are they pleasing and acceptable to God in Christ, and do spring out necessarily of a true and lively Faith; insomuch that by them a lively Faith may be as evidently known as a tree discerned by the fruit.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100013, 100, 13, 'Of Works before Justification', 1, 'Works done before the grace of Christ, and the Inspiration of his Spirit, are not pleasant to God, forasmuch as they spring not of faith in Jesus Christ, neither do they make men meet to receive grace, or (as the School-authors say) deserve grace of congruity: yea rather, for that they are not done as God hath willed and commanded them to be done, we doubt not but they have the nature of sin.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100014, 100, 14, 'Of Works of Supererogation', 1, 'Voluntary Works besides, over, and above, God''s Commandments, which they call Works of Supererogation, cannot be taught without arrogancy and impiety: for by them men do declare, that they do not only render unto God as much as they are bound to do, but that they do more for his sake, than of bounden duty is required: whereas Christ saith plainly, When ye have done all that are commanded to you, say, We are unprofitable servants.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100015, 100, 15, 'Of Christ alone without Sin', 1, 'Christ in the truth of our nature was made like unto us in all things, sin only except, from which he was clearly void, both in his flesh, and in his spirit. He came to be the Lamb without spot, who, by sacrifice of himself once made, should take away the sins of the world, and sin, as Saint John saith, was not in him. But all we the rest, although baptized, and born again in Christ, yet offend in many things; and if we say we have no sin, we deceive ourselves, and the truth is not in us.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100016, 100, 16, 'Of Sin after Baptism', 1, 'Not every deadly sin willingly committed after Baptism is sin against the Holy Ghost, and unpardonable. Wherefore the grant of repentance is not to be denied to such as fall into sin after Baptism. After we have received the Holy Ghost, we may depart from grace given, and fall into sin, and by the grace of God we may arise again, and amend our lives. And therefore they are to be condemned, which say, they can no more sin as long as they live here, or deny the place of forgiveness to such as truly repent.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100017, 100, 17, 'Of Predestination and Election', 1, 'Predestination to Life is the everlasting purpose of God, whereby (before the foundations of the world were laid) he hath constantly decreed by his counsel secret to us, to deliver from curse and damnation those whom he hath chosen in Christ out of mankind, and to bring them by Christ to everlasting salvation, as vessels made to honour. Wherefore, they which be endued with so excellent a benefit of God be called according to God''s purpose by his Spirit working in due season: they through Grace obey the calling: they be justified freely: they be made sons of God by adoption: they be made like the image of his only-begotten Son Jesus Christ: they walk religiously in good works, and at length, by God''s mercy, they attain to everlasting felicity. As the godly consideration of Predestination, and our Election in Christ, is full of sweet, pleasant, and unspeakable comfort to godly persons, and such as feel in themselves the working of the Spirit of Christ, mortifying the works of the flesh, and their earthly members, and drawing up their mind to high and heavenly things, as well because it doth greatly establish and confirm their faith of eternal Salvation to be enjoyed through Christ, as because it doth fervently kindle their love towards God: So, for curious and carnal persons, lacking the Spirit of Christ, to have continually before their eyes the sentence of God''s Predestination, is a most dangerous downfal, whereby the Devil doth thrust them either into desperation, or into wretchlessness of most unclean living, no less perilous than desperation. Furthermore, we must receive God''s promises in such wise, as they be generally set forth to us in holy Scripture: and, in our doings, that Will of God is to be followed, which we have expressly declared unto us in the Word of God.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100018, 100, 18, 'Of obtaining eternal Salvation only by the Name of Christ', 1, 'They also are to be had accursed that presume to say, That every man shall be saved by the Law or Sect which he professeth, so that he be diligent to frame his life according to that Law, and the light of Nature. For holy Scripture doth set out unto us only the Name of Jesus Christ, whereby men must be saved.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100019, 100, 19, 'Of the Church', 1, 'The visible Church of Christ is a congregation of faithful men, in the which the pure Word of God is preached, and the Sacraments be duly ministered according to Christ''s ordinance in all those things that of necessity are requisite to the same. As the Church of Jerusalem, Alexandria, and Antioch, have erred; so also the Church of Rome hath erred, not only in their living and manner of Ceremonies, but also in matters of Faith.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100020, 100, 20, 'Of the Authority of the Church', 1, 'The Church hath power to decree Rites or Ceremonies, and authority in Controversies of Faith: And yet it is not lawful for the Church to ordain any thing that is contrary to God''s Word written, neither may it so expound one place of Scripture, that it be repugnant to another. Wherefore, although the Church be a witness and a keeper of holy Writ, yet, as it ought not to decree any thing against the same, so besides the same ought it not to enforce any thing to be believed for necessity of Salvation.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100021, 100, 21, 'Of the Authority of General Councils', 1, 'General Councils may not be gathered together without the commandment and will of Princes. And when they be gathered together, (forasmuch as they be an assembly of men, whereof all be not governed with the Spirit and Word of God,) they may err, and sometimes have erred, even in things pertaining unto God. Wherefore things ordained by them as necessary to salvation have neither strength nor authority, unless it may be declared that they be taken out of holy Scripture.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100022, 100, 22, 'Of Purgatory', 1, 'The Romish Doctrine concerning Purgatory, Pardons, Worshipping, and Adoration, as well of Images as of Reliques, and also invocation of Saints, is a fond thing vainly invented, and grounded upon no warranty of Scripture, but rather repugnant to the Word of God.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100023, 100, 23, 'Of Ministering in the Congregation', 1, 'It is not lawful for any man to take upon him the office of publick preaching, or ministering the Sacraments in the Congregation, before he be lawfully called, and sent to execute the same. And those we ought to judge lawfully called and sent, which be chosen and called to this work by men who have publick authority given unto them in the Congregation, to call and send Ministers into the Lord''s vineyard.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100024, 100, 24, 'Of speaking in the Congregation in such a tongue as the people understandeth', 1, 'It is a thing plainly repugnant to the Word of God, and the custom of the Primitive Church, to have publick Prayer in the Church, or to minister the Sacraments in a tongue not understanded of the people.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100025, 100, 25, 'Of the Sacraments', 1, 'Sacraments ordained of Christ be not only badges or tokens of Christian men''s profession, but rather they be certain sure witnesses, and effectual signs of grace, and God''s good will towards us, by the which he doth work invisibly in us, and doth not only quicken, but also strengthen and confirm our Faith in him. There are two Sacraments ordained of Christ our Lord in the Gospel, that is to say, Baptism, and the Supper of the Lord. Those five commonly called Sacraments, that is to say, Confirmation, Penance, Orders, Matrimony, and extreme Unction, are not to be counted for Sacraments of the Gospel, being such as have grown partly of the corrupt following of the Apostles, partly are states of life allowed in the Scriptures; but yet have not like nature of Sacraments with Baptism, and the Lord''s Supper, for that they have not any visible sign or ceremony ordained of God. The Sacraments were not ordained of Christ to be gazed upon, or to be carried about, but that we should duly use them. And in such only as worthily receive the same they have a wholesome effect or operation: but they that receive them unworthily purchase to themselves damnation, as Saint Paul saith.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100026, 100, 26, 'Of the Unworthiness of the Ministers, which hinders not the effect of the Sacrament', 1, 'Although in the visible Church the evil be ever mingled with the good, and sometimes the evil have chief authority in the Ministration of the Word and Sacraments, yet forasmuch as they do not the same in their own name, but in Christ''s, and do minister by his commission and authority, we may use their Ministry, both in hearing the Word of God, and in receiving of the Sacraments. Neither is the effect of Christ''s ordinance taken away by their wickedness, nor the grace of God''s gifts diminished from such as by faith and rightly do receive the Sacraments ministered unto them; which be effectual, because of Christ''s institution and promise, although they be ministered by evil men. Nevertheless, it appertaineth to the discipline of the Church, that inquiry be made of evil Ministers, and that they be accused by those that have knowledge of their offences; and finally being found guilty, by just judgement be deposed.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100027, 100, 27, 'Of Baptism', 1, 'Baptism is not only a sign of profession, and mark of difference, whereby Christian men are discerned from others that be not christened, but it is also a sign of Regeneration or new Birth, whereby, as by an instrument, they that receive Baptism rightly are grafted into the Church; the promises of forgiveness of sin, and of our adoption to be the sons of God by the Holy Ghost, are visibly signed and sealed; Faith is confirmed, and Grace increased by virtue of prayer unto God. The Baptism of young Children is in any wise to be retained in the Church, as most agreeable with the institution of Christ.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100028, 100, 28, 'Of the Lord''s Supper', 1, 'The Supper of the Lord is not only a sign of the love that Christians ought to have among themselves one to another; but rather is a Sacrament of our Redemption by Christ''s death: insomuch that to such as rightly, worthily, and with faith, receive the same, the Bread which we break is a partaking of the Body of Christ; and likewise the Cup of Blessing is a partaking of the Blood of Christ. Transubstantiation (or the change of the substance of Bread and Wine) in the Supper of the Lord, cannot be proved by holy Writ; but is repugnant to the plain words of Scripture, overthroweth the nature of a Sacrament, and hath given occasion to many superstitions. The Body of Christ is given, taken, and eaten, in the Supper, only after an heavenly and spiritual manner. And the mean whereby the Body of Christ is received and eaten in the Supper is Faith. The Sacrament of the Lord''s Supper was not by Christ''s ordinance reserved, carried about, lifted up, or worshipped.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100029, 100, 29, 'Of the Wicked which eat not the Body of Christ in the use of the Lord''s Supper', 1, 'The Wicked, and such as be void of a lively faith, although they do carnally and visibly press with their teeth (as Saint Augustine saith) the Sacrament of the Body and Blood of Christ, yet in no wise are they partakers of Christ: but rather, to their condemnation, do eat and drink the sign or Sacrament of so great a thing.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100030, 100, 30, 'Of both kinds', 1, 'The Cup of the Lord is not to be denied to the Lay-people: for both the parts of the Lord''s Sacrament, by Christ''s ordinance and commandment, ought to be ministered to all Christian men alike.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100031, 100, 31, 'Of the one Oblation of Christ finished upon the Cross', 1, 'The Offering of Christ once made is that perfect redemption, propitiation, and satisfaction, for all the sins of the whole world, both original and actual; and there is none other satisfaction for sin, but that alone. Wherefore the sacrifices of Masses, in the which it was commonly said, that the Priest did offer Christ for the quick and the dead, to have remission of pain or guilt, were blasphemous fables, and dangerous deceits.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100032, 100, 32, 'Of the Marriage of Priests', 1, 'Bishops, Priests, and Deacons, are not commanded by God''s Law, either to vow the estate of single life, or to abstain from marriage: therefore it is lawful for them, as for all other Christian men, to marry at their own discretion, as they shall judge the same to serve better to godliness.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100033, 100, 33, 'Of Excommunicate Persons, how they are to be avoided', 1, 'That person which by open denunciation of the Church is rightly cut off from the unity of the Church, and excommunicated, ought to be taken of the whole multitude of the faithful, as an Heathen and Publican, until he be openly reconciled by penance, and received into the Church by a Judge that hath authority thereunto.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100034, 100, 34, 'Of the Traditions of the Church', 1, 'It is not necessary that Traditions and Ceremonies be in all places one, and utterly like; for at all times they have been divers, and may be changed according to the diversities of countries, times, and men''s manners, so that nothing be ordained against God''s Word. Whosoever through his private judgement, willingly and purposely, doth openly break the traditions and ceremonies of the Church, which be not repugnant to the Word of God, and be ordained and approved by common authority, ought to be rebuked openly, (that others may fear to do the like,) as he that offendeth against the common order of the Church, and hurteth the authority of the Magistrate, and woundeth the consciences of the weak brethren. Every particular or national Church hath authority to ordain, change, and abolish, ceremonies or rites of the Church ordained only by man''s authority, so that all things be done to edifying.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100035, 100, 35, 'Of the Homilies', 1, 'The second Book of Homilies, the several titles whereof we have joined under this Article, doth contain a godly and wholesome Doctrine, and necessary for these times, as doth the former Book of Homilies, which were set forth in the time of Edward the Sixth; and therefore we judge them to be read in Churches by the Ministers, diligently and distinctly, that they may be understanded of the people. Of the Names of the Homilies 1.Of the right Use of the Church. 2.Against peril of Idolatry. 3.Of repairing and keeping clean of Churches. 4.Of good Works: first of Fasting. 5.Against Gluttony and Drunkenness. 6.Against Excess of Apparel. 7.Of Prayer. 8.Of the Place and Time of Prayer. 9.That Common Prayers and Sacraments ought to be ministered in a known tongue. 10.Of the reverend estimation of God''s Word. 11.Of Alms-doing. 12.Of the Nativity of Christ. 13.Of the Passion of Christ. 14.Of the Resurrection of Christ. 15.Of the worthy receiving of the Sacrament of the Body and Blood of Christ. 16.Of the Gifts of the Holy Ghost. 17.For the Rogation-days. 18.Of the State of Matrimony. 19.Of Repentance. 20.Against Idleness. 21.Against Rebellion.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100036, 100, 36, 'Of Consecration of Bishops and Ministers', 1, 'The Book of Consecration of Archbishops and Bishops, and Ordering of Priests and Deacons, lately set forth in the time of Edward the Sixth, and confirmed at the same time by authority of Parliament, doth contain all things necessary to such Consecration and Ordering: neither hath it any thing, that of itself is superstitious and ungodly. And therefore whosoever are consecrated or ordered according to the Rites of that Book, since the second year of the forenamed King Edward unto this time, or hereafter shall be consecrated or ordered according to the same Rites; we decree all such to be rightly, orderly, and lawfully consecrated and ordered.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100037, 100, 37, 'Of the Civil Magistrates', 1, 'The King''s Majesty hath the chief power in this Realm of England, and other his Dominions, unto whom the chief Government of all Estates of this Realm, whether they be Ecclesiastical or Civil, in all causes doth appertain, and is not, nor ought to be, subject to any foreign Jurisdiction. Where we attribute to the King''s Majesty the chief government, by which Titles we understand the minds of some slanderous folks to be offended; we give not to our Princes the ministering either of God''s Word, or of the Sacraments, the which thing the Injunctions also lately set forth by Elizabeth our Queen do most plainly testify; but that only prerogative, which we see to have been given always to all godly Princes in holy Scriptures by God himself; that is, that they should rule all estates and degrees committed to their charge by God, whether they be Ecclesiastical or Temporal, and restrain with the civil sword the stubborn and evil-doers. The Bishop of Rome hath no jurisdiction in this Realm of England. The Laws of the Realm may punish Christian men with death, for heinous and grievous offences. It is lawful for Christian men, at the commandment of the Magistrate, to wear weapons, and serve in the wars.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100038, 100, 38, 'Of Christian men''s Goods, which are not common', 1, 'The Riches and Goods of Christians are not common, as touching the right, title, and possession of the same, as certain Anabaptists do falsely boast. Notwithstanding, every man ought, of such things as he possesseth, liberally to give alms to the poor, according to his ability.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (100039, 100, 39, 'Of a Christian man''s Oath', 1, 'As we confess that vain and rash Swearing is forbidden Christian men by our Lord Jesus Christ, and James his Apostle, so we judge, that Christian Religion doth not prohibit, but that a man may swear when the Magistrate requireth, in a cause of faith and charity, so it be done according to the Prophet''s teaching, in justice, judgement, and truth. This Book of Articles before rehearsed, is again approved, and allowed to be holden and executed within the Realm, by the assent and consent of our Sovereign Lady ELIZABETH, by the grace of God, of England, France, and Ireland, Queen, Defender of the Faith, &c. Which Articles were deliberately read, and confirmed again by the subscription of the hands of the Archbishop and Bishops of the Upper-house, and by the subscription of the whole Clergy of the Nether-house in their Convocation, in the Year of our Lord 1571.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101001, 101, 1, 'Of Faith in the Holy Trinity', 1, 'There is but one living and true God, everlasting, without body or parts, of infinite power, wisdom, and goodness; the Maker and Preserver of all things, visible and invisible. And in unity of this Godhead there are three persons, of one substance, power, and eternity, the Father, the Son, and the Holy Ghost.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101002, 101, 2, 'Of the Word, or Son of God, who Was Made Very Man', 1, 'The Son, who is the Word of the Father, the very and eternal God, of one substance with the Father, took man''s nature in the womb of the blessed Virgin; so that two whole and perfect natures--that is to say, the Godhead and manhood--were joined together in one person, never to be divided, whereof is one Christ, very God and very man, who truly suffered, was crucified, dead and buried, to reconcile his Father to us, and to be a sacrifice, not only for original guilt, but also for the actual sins of men.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101003, 101, 3, 'Of the Resurrection of Christ', 1, 'Christ did truly rise again from the dead, and took again his body, with all things appertaining to the perfection of man''s nature, wherewith he ascended into heaven, and there sitteth until he return to judge all men at the last day.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101004, 101, 4, 'Of the Holy Ghost', 1, 'The Holy Ghost, proceeding from the Father and the Son, is of one substance, majesty, and glory with the Father and the Son, very and eternal God.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101005, 101, 5, 'The Sufficiency of the Holy Scriptures for Salvation', 1, 'The Holy Scriptures contain all things necessary to salvation; so that whatsoever is not read therein, nor may be proved thereby, is not to be required of any man that it should be believed as an article of faith, or be thought requisite or necessary to salvation. In the name of the Holy Scripture we do understand those canonical books of the Old and New Testament of whose authority was never any doubt in the Church. The names of the canonical books are-- Genesis, Exodus, Leviticus, Numbers, Deuteronomy, Joshua, Judges, Ruth, The First Book of Samuel, The Second Book of Samuel, The First Book of Kings, The Second Book of Kings, The First Book of Chronicles, The Second Book of Chronicles, The Book of Ezra, The Book of Nehemiah, The Book of Esther, The Book of Job, The Psalms, The Proverbs, Ecclesiastes or the Preacher, Cantica or Songs of Solomon, Four Prophets the greater, Twelve Prophets the less. All the books of the New Testament, as they are commonly received, we do receive and account canonical.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101006, 101, 6, 'Of the Old Testament', 1, 'The Old Testament is not contrary to the New; for both in the Old and New Testament everlasting life is offered to mankind by Christ, who is the only Mediator between God and man, being both God and man. Wherefore they are not to be heard who feign that the old fathers did look only for transitory promises. Although the law given from God by Moses, as touching ceremonies and rites, doth not bind Christians, nor ought the civil precepts thereof of necessity be received in any commonwealth, yet, notwithstanding, no Christian whatsoever is free from the obedience of the commandments which are called moral.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101007, 101, 7, 'Of Original or Birth Sin', 1, 'Original sin standeth not in the following of Adam (as the Pelagians do vainly talk), but it is the corruption of the nature of every man, that naturally is engendered of the offspring of Adam, whereby man is very far gone from original righteousness, and of his own nature inclined to evil, and that continually.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101008, 101, 8, 'Of Free Will', 1, 'The condition of man after the fall of Adam is such that he can not turn and prepare himself, by his own natural strength and works, to faith and calling upon God; wherefore we have no power to do good works, pleasant and acceptable to God, without the grace of God by Christ preventing us, that we may have a good will, and working with us, when we have that good will.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101009, 101, 9, 'Of the Justification of Man', 1, 'We are accounted righteous before God only for the merit of our Lord and Saviour Jesus Christ by faith, and not for our own works or deservings. Wherefore, that we are justified by faith only is a most wholesome doctrine, and very full of comfort.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101010, 101, 10, 'Of Good Works', 1, 'Although good works, which are the fruits of faith, and follow after justification, can not put away our sins, and endure the severity of God''s judgments; yet are they pleasing and acceptable to God in Christ, and spring out of a true and lively faith, insomuch that by them a lively faith may be as evidently known as a tree is discerned by its fruit.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101011, 101, 11, 'Of Works of Supererogation', 1, 'Voluntary works--besides, over, and above God''s commandments--which are called works of supererogation, can not be taught without arrogancy and impiety. For by them men do declare that they do not only render unto God as much as they are bound to do, but that they do more for his sake than of bounden duty is required: whereas Christ saith plainly, When ye have done all that is commanded you, say, We are unprofitable servants.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101012, 101, 12, 'Of Sin After Justification', 1, 'Not every sin willingly committed after justification is the sin against the Holy Ghost, and unpardonable. Wherefore, the grant of repentance is not to be denied to such as fall into sin after justification: after we have received the Holy Ghost, we may depart from grace given, and fall into sin, and, by the grace of God, rise again and amend our lives. And therefore they are to be condemned who say they can no more sin as long as they live here; or deny the place of forgiveness to such as truly repent.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101013, 101, 13, 'Of the Church', 1, 'The visible Church of Christ is a congregation of faithful men, in which the pure Word of God is preached, and the sacraments duly administered, according to Christ''s ordinance, in all those things that of necessity are requisite to the same.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101014, 101, 14, 'Of Purgatory', 1, 'The Romish doctrine concerning purgatory, pardon, worshiping, and adoration, as well of images as of relics, and also invocation of saints, is a fond thing, vainly invented, and grounded upon no warrant of Scripture, but repugnant to the Word of God.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101015, 101, 15, 'Of Speaking in the Congregation in Such a Tongue as the People Understand', 1, 'It is a thing plainly repugnant to the Word of God, and the custom of the primitive Church, to have public prayer in the Church, or to minister the sacraments, in a tongue not understood by the people.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101016, 101, 16, 'Of the Sacraments', 1, 'Sacraments ordained of Christ are not only badges or tokens of Christian men''s profession, but rather they are certain signs of grace, and God''s good will toward us, by the which he doth work invisibly in us, and doth not only quicken, but also strengthen and confirm our faith in him. There are two sacraments ordained of Christ our Lord in the Gospel; that is to say, Baptism and the Supper of the Lord. Those five commonly called sacraments, that is to say, confirmation, penance, orders, matrimony, and extreme unction, are not to be counted for sacraments of the gospel, being such as have partly grown out of the corrupt following of the apostles; and partly are states of life allowed in the Scriptures, but yet have not the like nature of Baptism and the Lord''s Supper, because they have not any visible sign or ceremony ordained of God. The sacraments were not ordained of Christ to be gazed upon, or to be carried about, but that we should duly use them. And in such only as worthily receive the same they have a wholesome effect or operation; but they that receive them unworthily purchase to themselves condemnation, as St. Paul saith, 1 Cor. xi. 29.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101017, 101, 17, 'Of Baptism', 1, 'Baptism is not only a sign of profession, and mark of difference, whereby Christians are distinguished from others that are not baptized; but it is also a sign of regeneration, or the new birth. The baptism of young children is to be retained in the Church.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101018, 101, 18, 'Of the Lord''s Supper', 1, 'The Supper of the Lord is not only a sign of the love that Christians ought to have among themselves one to another, but rather is a sacrament of our redemption by Christ''s death; insomuch that, to such as rightly, worthily, and with faith receive the same, the bread which we break is a partaking of the body of Christ; and likewise the cup of blessing is a partaking of the blood of Christ. Transubstantiation, or the change of the substance of bread and wine in the Supper of our Lord, can not be proved by Holy Writ, but is repugnant to the plain words of Scripture, overthroweth the nature of a sacrament, and hath given occasion to many superstitions. The body of Christ is given, taken, and eaten in the Supper only after a heavenly and spiritual manner. And the means whereby the body of Christ is received and eaten in the Supper is faith. The sacrament of the Lord''s Supper was not by Christ''s ordinance reserved, carried about, lifted up, or worshiped.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101019, 101, 19, 'Of Both Kinds', 1, 'The cup of the Lord is not to be denied to the lay people; for both the parts of the Lord''s Supper, by Christ''s ordinance and commandment, ought to be administered to all Christians alike.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101020, 101, 20, 'Of the One Oblation of Christ, Finished Upon the Cross', 1, 'The offering of Christ, once made, is that perfect redemption, propitiation, and satisfaction for all the sins of the whole world, both original and actual; and there is none other satisfaction for sin but that alone. Wherefore the sacrifice of masses, in the which it is commonly said that the priest doth offer Christ for the quick and the dead, to have remission of pain or guilt, is a blasphemous fable and dangerous deceit.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101021, 101, 21, 'Of the Marriage of Ministers', 1, 'The ministers of Christ are not commanded by God''s law either to vow the estate of single life or to abstain from marriage: therefore it is lawful for them, as for all other Christians, to marry at their own discretion, as they shall judge the same to serve best to godliness.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101022, 101, 22, 'Of the Rites and Ceremonies of Churches', 1, 'It is not necessary that rites and ceremonies should in all places be the same, or exactly alike; for they have been always different, and may be changed according to the diversity of countries, times, and men''s manners, so that nothing be ordained against God''s Word. Whosoever, through his private judgment, willingly and purposely doth openly break the rites and ceremonies of the Church to which he belongs, which are not repugnant to the Word of God, and are ordained and approved by common authority, ought to be rebuked openly, that others may fear to do the like, as one that offendeth against the common order of the Church, and woundeth the consciences of weak brethren. Every particular Church may ordain, change, or abolish rites and ceremonies, so that all things may be done to edification.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101023, 101, 23, 'Of the Rulers of the United States of America', 1, 'The President, the Congress, the General Assemblies, the Governors, and the Councils of State, as the delegates of the people, are the rulers of the United States of America, according to the division of power made to them by the Constitution of the United States, and by the Constitutions of their respective States. And the said States are a sovereign and independent nation, and ought not to be subject to any foreign jurisdiction.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101024, 101, 24, 'Of Christian Men''s Goods', 1, 'The riches and goods of Christians are not common, as touching the right, title, and possession of the same, as some do falsely boast. Notwithstanding, every man ought, of such things as he possesseth, liberally to give alms to the poor, according to his ability.');
INSERT OR REPLACE INTO confessional_sections (id, document_id, chapter_number, chapter_title, section_number, content) VALUES (101025, 101, 25, 'Of a Christian Man''s Oath', 1, 'As we confess that vain and rash swearing is forbidden Christian men by our Lord Jesus Christ and James his apostle, so we judge that the Christian religion doth not prohibit but that a man may swear when the magistrate requireth, in a cause of faith and charity, so it be done according to the prophet''s teaching, in justice, judgment, and truth.');
